const CL_REJ = ["S0", "S1", "S2", "S3", "S4", "R1", "R2", "R3", "RX"];
const clIsRej = (t) => ["R1", "R2", "R3", "RX"].includes(t.state) || (t.rejection && CL_FLOW[t.state].terminal);
