const clTatLabel = (t) => { const T = CL_FLOW[t.state].tat; if (!T) return "-"; return T.v + " " + (T.unit === "BH" ? (T.v === 1 ? "business hour" : "business hours") : (T.v === 1 ? "working day" : "working days")); };

